const state={client:null,role:'viewer',user:null,stageMap:{},opps:[],months:[],deliveries:[],components:[],notes:[],revisions:[],solutionOverrides:[],syncing:false,sfSynced:false,syncError:null,lastSyncAt:null,lastSyncDeliveries:null,lastDeliverySyncAt:null,anchor:quarterStart(new Date()),filters:{lifecycle:'quarter',account:'',stage:'',solution:'',focus:''},subview:'forecast',selected:null,remainingOpen:false,pipelineOpen:false,slackTesting:false,slackTestMessage:null,loading:false,error:null,noteTimers:new Map()};
