function accountOptionsSince(opps,months,startDate='2026-01-01'){const eligibleOpportunityIds=new Set(months.filter(m=>m?.salesforce_present!==false&&String(m?.schedule_date||'')>=startDate).map(m=>m.opportunity_id).filter(Boolean));return[...new Set(opps.filter(o=>eligibleOpportunityIds.has(o.id)).map(o=>o.account_name).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
const conflict=m=>!!m?.is_dirty&&Number(m?.working_base_salesforce)!==Number(m?.current_salesforce);
const canEdit=()=>state.role==='editor';
const activeComponents=id=>state.components.filter(c=>c.forecast_month_id===id&&c.is_active!==false&&c.created_by).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));
const displayComponents=id=>state.components.filter(c=>c.forecast_month_id===id&&c.is_active!==false&&!c.created_by).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));
const monthFor=(opId,key)=>state.months.find(m=>m.opportunity_id===opId&&monthKey(m.schedule_date)===key&&m.salesforce_present!==false);
// Paychex Q3: TechnologyAdvice is a verified pass-through partner (client and partner CPL $39).
// Keep source records intact; exclude only this program partner from Revenue HQ actuals.
const deliveryIncluded=(op,d)=>!(String(op?.account_name||'').trim().toLowerCase()==='paychex'&&d.salesforce_program_partner_id==='a01Rd00000nKW7ZIAW');
const deliveryRowsFor=(op,key)=>state.deliveries.filter(d=>deliveryIncluded(op,d)&&d.salesforce_present!==false&&d.salesforce_opportunity_id===op.salesforce_opportunity_id&&monthKey(d.delivery_date)===key);
const actualFor=(op,key)=>deliveryRowsFor(op,key).reduce((a,d)=>({revenue:a.revenue+Number(d.client_delivery_revenue||0),volume:a.volume+Number(d.delivered_volume||0)}),{revenue:0,volume:0});
