const deliveryProgramsFor=(op,key)=>{const map=new Map();for(const d of deliveryRowsFor(op,key)){const k=d.salesforce_program_id||d.program_name||'Unknown Program',v=map.get(k)||{programName:d.program_name||'Program',revenue:0,volume:0};v.revenue+=Number(d.client_delivery_revenue||0);v.volume+=Number(d.delivered_volume||0);map.set(k,v)}return [...map.values()].sort((a,b)=>b.revenue-a.revenue)};
