 const call=async action=>{const {data,error}=await state.client.functions.invoke('revenue-hq-slack-check',{body:{action}});if(error){let message=error.message;try{const details=await error.context?.json?.();message=details?.error||message}catch{}throw new Error(message||'Slack check failed.')}if(!data?.ok)throw new Error(data?.error||'Slack check failed.');return data;};
 try{const status=await call('status');if(!status.configured||!status.webhookValid)throw new Error('The Revenue HQ Slack webhook is missing or invalid.');const result=await call('preview');state.slackTestMessage=result.sent?'Sample digest accepted by Slack. Check #revenue-hq-updates. Daily digest remains disabled.':'Slack did not confirm sending the test.';}
