function componentRow(c,i){return `<div class="rf-component" data-component="${c.id}"><input class="rf-component-name" value="${esc(c.component_name)}" ${canEdit()?'':'disabled'}><input class="rf-component-amount" type="number" step="0.01" value="${Number(c.amount||0).toFixed(2)}" ${canEdit()?'':'disabled'}>${canEdit()?`<button data-save-component="${c.id}" data-updated="${c.updated_at}" data-order="${i}">Save</button><button data-remove-component="${c.id}" data-updated="${c.updated_at}">Remove</button>`:''}</div>`}
